IDS = ['WP-008','WP-009','WP-010','WP-011','WP-012','WP-013','YM-002','YM-003','YM-004','YM-005','YM-007','YM-008','YM-009','YM-010','YM-012','YM-013','YM-014','YM-015','YM-017','YM-018']
assert len(IDS) == 20 and set(IDS) == set(P), (len(IDS), set(IDS) ^ set(P))

total = 0
for cid in IDS:
    rec = {"case_id": cid, "prediction_text": P[cid]["prediction_text"], "basis": P[cid]["basis"],
           "confidence": P[cid]["confidence"], "trigger": P[cid]["trigger"]}
    data = json.dumps(rec, ensure_ascii=False, indent=1).encode('utf-8')
    (OUT / f'{cid}.json').write_bytes(data)
    total += len(data)

# 逐件自验
ok = 0
trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in IDS:
    d = json.loads((OUT / f'{cid}.json').read_text(encoding='utf-8'))
    assert d['case_id'] == cid
    assert set(d.keys()) == {'case_id','prediction_text','basis','confidence','trigger'}
    assert 0 <= d['confidence'] <= 1 and d['prediction_text'] and d['basis']
    assert set(d['trigger'].keys()) == {'changed_main','reserve_used','disputed','reason'}
    for k in trig: trig[k] += 1 if d['trigger'][k] else 0
    ok += 1
print('written_ok =', ok)
print('trigger_counts =', trig)
print('total_bytes =', total)
